3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { useConversation } from "@elevenlabs/react";
5	import { TRANSCRIPT_SCRIPT, type Persona, type Provider } from "@/lib/data";
6	import type { CallState, SessionApi, SessionTurn } from "./types";
7	import { useXaiSession } from "./use-xai-session";
8	import { useOpenaiSession } from "./use-openai-session";
9	import { useGeminiSession } from "./use-gemini-session";
10	import { useCascadeSession } from "./use-cascade-session";
11	import { useFalSession } from "./use-fal-session";
12	import { useMoshiSession } from "./use-moshi-session";
13	
14	const SCRIPT_TURNS: SessionTurn[] = TRANSCRIPT_SCRIPT.map((t, i) => ({
15	  id: `s${i}`,
16	  who: t.who,
17	  text: t.text,
18	}));
19	
20	const LAST = TRANSCRIPT_SCRIPT.length - 1;
21	
22	function mockCaption(state: CallState): string {
23	  switch (state) {
24	    case "idle":
25	      return "press CALL to begin";
26	    case "ended":
27	      return "— call ended —";
28	    case "connecting":
29	      return "establishing session…";
30	    case "listening":
31	      return TRANSCRIPT_SCRIPT[LAST - 1].text;
32	    case "speaking":
33	      return TRANSCRIPT_SCRIPT[LAST].text;
34	    case "interrupted":
35	      return "… you interrupted";
36	  }
37	}
38	
39	/**
40	 * Unified realtime session. `provider.engine` selects the engine:
41	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
42	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
43	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
44	 *   - "openai" → real gpt-realtime voice via WebRTC (useOpenaiSession)
45	 *   - "gemini" → real Gemini Live voice via a direct WebSocket (useGeminiSession)
46	 *   - "fal" → full-duplex PersonaPlex via a direct WebSocket (useFalSession)
47	 *   - "moshi" → full-duplex PersonaPlex on the LOCAL MLX server (useMoshiSession)
48	 * All expose the same `SessionApi` so the UI is provider-agnostic.
49	 *
50	 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
