SP=/private/tmp/claude-501/-Users-jessearmand-Develop-realtime-persona--claude-worktrees-elevenlabs-voice-agents-07030a/83aabdbb-1dd7-4229-86f6-b237c0b0d634/scratchpad; cat > $SP/diff-agents.ts <<'EOF'
import { readFileSync } from "node:fs";
const SP = process.argv[2];
const IDS = ["aria","onyx","sage","nova","echo","cipher","vesper"];
type J = any;
const get = (o: J, path: string[]) => path.reduce((a, k) => (a == null ? undefined : a[k]), o);
function leaves(o: J, prefix: string[] = []): string[][] {
  if (o === null || typeof o !== "object" || Array.isArray(o)) return [prefix];
  return Object.keys(o).flatMap((k) => leaves(o[k], [...prefix, k]));
}
const fmt = (v: J) => { const s = JSON.stringify(v); return s && s.length > 90 ? s.slice(0, 87) + "…" : s; };

// (a) lean (what we pushed) vs platform (what's there now)
console.log("=== A. Pushed (lean) vs platform now ===");
const pulled: Record<string, J> = {};
for (const id of IDS) {
  const lean = JSON.parse(readFileSync(`agent_configs/tsubaki-${id}.json`, "utf8"));
  const plat = JSON.parse(readFileSync(`${SP}/platform/agent_configs/tsubaki-${id}.json`, "utf8"));
  pulled[id] = plat;
  const diffs = leaves(lean).filter((p) => JSON.stringify(get(lean, p)) !== JSON.stringify(get(plat, p)));
  console.log(`\n── ${id}: ${diffs.length} changed`);
  for (const p of diffs) console.log(`  ${p.join(".")}\n    pushed:   ${fmt(get(lean, p))}\n    platform: ${fmt(get(plat, p))}`);
}

// (b) cross-agent variance on platform, excluding per-persona fields
console.log("\n=== B. Platform fields that differ between agents (beyond per-persona casting) ===");
const PERSONA = new Set(["name","conversation_config.tts.voice_id","conversation_config.tts.speed","conversation_config.turn.turn_eagerness","conversation_config.turn.turn_timeout","conversation_config.agent.first_message","conversation_config.agent.prompt.prompt"]);
const all = new Map<string, Map<string, string[]>>();
for (const id of IDS) for (const p of leaves(pulled[id])) {
  const k = p.join("."); if (PERSONA.has(k)) continue;
  const v = JSON.stringify(get(pulled[id], p)) ?? "undefined";
  const m = all.get(k) ?? new Map(); m.set(v, [...(m.get(v) ?? []), id]); all.set(k, m);
}
for (const [k, m] of all) if (m.size > 1) { console.log(`\n  ${k}`); for (const [v, ids] of m) console.log(`    ${ids.join(",")}: ${v.length > 90 ? v.slice(0,87)+"…" : v}`); }
EOF
bun run $SP/diff-agents.ts $SP

